test({ sr: 'počinje od 1 po defaultu', en: 'starts from 1 by default' }, () => {
  const c = createCounter();
  expect(c()).toBe(1);
  expect(c()).toBe(2);
});
test({ sr: 'poštuje početnu vrednost', en: 'respects the start value' }, () => {
  const c = createCounter(10);
  expect(c()).toBe(11);
});

hiddenTests:
test('counters are independent', () => {
  const a = createCounter();
  const b = createCounter();
  a();
  a();
  expect(b()).toBe(1);
});
test('a negative start value', () => {
  const c = createCounter(-5);
  expect(c()).toBe(-4);
});
test('many calls keep counting', () => {
  const c = createCounter();
  let last = 0;
  for (let i = 0; i < 100; i++) last = c();
  expect(last).toBe(100);
});

solutions.code:
function createCounter(start = 0) {
  let count = start;
  return () => ++count;
}
